use aap::caps::kb_read;
use aap::caps::tool_llm::{self, Reply};
use crate::aap::caps::types::{AgentResponse, LlmError};

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        if ctx.question.len() > 512 {
            return ResponseResult::Error(LlmError {
                message: "question exceeds maximum length".to_string(),
            });
        }

        let system = "You are a customer support assistant. Use the \
                       provided knowledge to answer the question. If you \
                       need more information, you may look up the \
                       knowledge base."
            .to_string();

        let mut prompt = String::new();
        prompt.push_str("Question: ");
        prompt.push_str(&ctx.question);
        if !ctx.knowledge.is_empty() {
            prompt.push_str("\nKnowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        match tool_llm::generate(&system, &prompt) {
            Reply::Text(text) => ResponseResult::Ok(AgentResponse { text }),
            Reply::Call(tool_request) => {
                let results = kb_read::lookup(&tool_request.query);

                let mut follow_up_prompt = prompt;
                follow_up_prompt.push_str("\nTool results for '");
                follow_up_prompt.push_str(&tool_request.query);
                follow_up_prompt.push_str("':\n");
                for r in &results {
                    follow_up_prompt.push_str("- ");
                    follow_up_prompt.push_str(r);
                    follow_up_prompt.push('\n');
                }

                match tool_llm::generate(&system, &follow_up_prompt) {
                    Reply::Text(text) => ResponseResult::Ok(AgentResponse { text }),
                    Reply::Call(_) => ResponseResult::Error(LlmError {
                        message: "model requested a second tool call".to_string(),
                    }),
                }
            }
        }
    }
}

export!(Node);
